import * as React from "react"

import { cn } from "@/lib/utils"

// Control Room Item: console list row.
// Square recessed leading well for the icon, mono title, quiet hover
// brightening like a focused log line.

interface ItemProps extends React.HTMLAttributes<HTMLDivElement> {
  leading?: React.ReactNode
  trailing?: React.ReactNode
  title: string
  subtitle?: string
  disabled?: boolean
  interactive?: boolean
  as?: React.ElementType
  href?: string
}

const Item = React.forwardRef<HTMLDivElement, ItemProps>(
  (
    {
      leading,
      trailing,
      title,
      subtitle,
      disabled,
      interactive = true,
      as: Comp = "div",
      className,
      children,
      ...props
    },
    ref
  ) => {
    return (
      <Comp
        ref={ref}
        className={cn(
          "group flex w-full items-center gap-3 px-3 py-2.5",
          "text-left",
          interactive && [
            "cursor-pointer rounded-sm",
            "transition-colors duration-fast",
            "hover:bg-accent/50",
            "focus-visible:outline-none focus-visible:bg-accent focus-visible:ring-2 focus-visible:ring-ring/60",
            "active:bg-accent",
          ],
          disabled && "pointer-events-none opacity-40",
          className
        )}
        {...props}
      >
        {/* Leading slot: icon or avatar */}
        {leading && (
          <div
            className={cn(
              "flex h-8 w-8 shrink-0 items-center justify-center",
              "rounded-xs border border-border bg-input",
              "[box-shadow:var(--shadow-inset)]",
              "text-muted-foreground",
              "[&>svg]:size-4",
              "transition-colors duration-fast group-hover:text-primary"
            )}
          >
            {leading}
          </div>
        )}

        {/* Text content */}
        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <span className="truncate text-xs font-semibold leading-snug text-foreground">
            {title}
          </span>
          {subtitle && (
            <span className="truncate text-[0.6875rem] leading-snug text-muted-foreground">
              {subtitle}
            </span>
          )}
          {children}
        </div>

        {/* Trailing slot: action, badge, arrow, toggle */}
        {trailing && (
          <div className="flex shrink-0 items-center gap-2 text-muted-foreground [&>svg]:size-4">
            {trailing}
          </div>
        )}
      </Comp>
    )
  }
)
Item.displayName = "Item"

// Item list container for grouped items
interface ItemListProps extends React.HTMLAttributes<HTMLDivElement> {
  divided?: boolean
}

const ItemList = React.forwardRef<HTMLDivElement, ItemListProps>(
  ({ divided = false, className, children, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          "flex flex-col",
          divided && [
            "[&>*:not(:last-child)]:border-b",
            "[&>*:not(:last-child)]:border-border",
          ],
          className
        )}
        {...props}
      >
        {children}
      </div>
    )
  }
)
ItemList.displayName = "ItemList"

export { Item, ItemList }
export type { ItemProps, ItemListProps }
